package com.axiom.application.analysis;import com.axiom.domain.failure.FailureClassification;import java.util.*;import org.springframework.stereotype.Service;
@Service public class PipelineTriageService {public Result triage(List<Failure> failures,boolean unchangedRerunPass,boolean relatedChange){if(failures.isEmpty())return new Result(null,"UNKNOWN","INSUFFICIENT_EVIDENCE","No extracted failure events are available.");Failure primary=failures.stream().max(Comparator.comparingDouble(this::score)).orElseThrow();double s=score(primary);String rerun;if(primary.classification()==FailureClassification.BUILD_FAILURE||primary.classification()==FailureClassification.DEPENDENCY_FAILURE||relatedChange)rerun="NOT_RECOMMENDED";else if(unchangedRerunPass||primary.classification()==FailureClassification.INFRASTRUCTURE_FAILURE||primary.classification()==FailureClassification.ENVIRONMENT_FAILURE)rerun="RECOMMENDED";else rerun="CONSIDER";return new Result(primary.fingerprint(),role(s),rerun,"The "+primary.classification().name().toLowerCase().replace('_',' ')+" appears to be the highest-priority failure signal.");}private double score(Failure f){double v=switch(f.classification()){case RESOURCE_EXHAUSTION,INFRASTRUCTURE_FAILURE,DEPENDENCY_FAILURE->.9;case BUILD_FAILURE,CONFIGURATION_FAILURE->.8;case TEST_FAILURE->.55;default->.3;};if(f.generic())v-=.5;return v;}private String role(double x){return x>=.6?"PRIMARY":"UNKNOWN";}public record Failure(String fingerprint,FailureClassification classification,boolean generic){}public record Result(String primaryFingerprint,String primaryRole,String rerunRecommendation,String summary){}}
